CREATE TABLE ingredients(id TEXT PRIMARY KEY,name TEXT NOT NULL,unit TEXT NOT NULL CHECK(unit IN('g','ml','piece')),stock_milli INTEGER NOT NULL CHECK(stock_milli>=0),reorder_level_milli INTEGER NOT NULL DEFAULT 0 CHECK(reorder_level_milli>=0),active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE recipes(product_id TEXT NOT NULL REFERENCES products(id),ingredient_id TEXT NOT NULL REFERENCES ingredients(id),quantity_milli INTEGER NOT NULL CHECK(quantity_milli>0),PRIMARY KEY(product_id,ingredient_id));
CREATE TABLE order_ingredients(order_id TEXT NOT NULL REFERENCES orders(id) ON DELETE CASCADE,ingredient_id TEXT NOT NULL REFERENCES ingredients(id),quantity_milli INTEGER NOT NULL CHECK(quantity_milli>0),released INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(order_id,ingredient_id));
CREATE TRIGGER royal_ingredient_check BEFORE INSERT ON orders WHEN NOT EXISTS(SELECT 1 FROM orders WHERE id=NEW.id) BEGIN SELECT CASE WHEN EXISTS(SELECT r.ingredient_id FROM json_each(NEW.items) j JOIN recipes r ON r.product_id=json_extract(j.value,'$.id') JOIN ingredients i ON i.id=r.ingredient_id GROUP BY r.ingredient_id HAVING MIN(i.active)=0 OR MIN(i.stock_milli)<SUM(r.quantity_milli*json_extract(j.value,'$.quantity'))) THEN RAISE(ABORT,'insufficient_ingredient') END; END;
CREATE TRIGGER royal_ingredient_record AFTER INSERT ON orders BEGIN INSERT INTO order_ingredients(order_id,ingredient_id,quantity_milli) SELECT NEW.id,r.ingredient_id,SUM(r.quantity_milli*json_extract(j.value,'$.quantity')) FROM json_each(NEW.items) j JOIN recipes r ON r.product_id=json_extract(j.value,'$.id') GROUP BY r.ingredient_id; END;
CREATE TRIGGER royal_ingredient_debit AFTER INSERT ON order_ingredients BEGIN UPDATE ingredients SET stock_milli=stock_milli-NEW.quantity_milli WHERE id=NEW.ingredient_id; END;
CREATE TRIGGER royal_ingredient_release AFTER UPDATE OF status ON orders WHEN NEW.status='cancelled' AND OLD.status!='cancelled' BEGIN UPDATE ingredients SET stock_milli=stock_milli+(SELECT quantity_milli FROM order_ingredients x WHERE x.order_id=NEW.id AND x.ingredient_id=ingredients.id AND x.released=0) WHERE id IN(SELECT ingredient_id FROM order_ingredients WHERE order_id=NEW.id AND released=0); UPDATE order_ingredients SET released=1 WHERE order_id=NEW.id AND released=0; END;
CREATE TABLE product_images(id TEXT PRIMARY KEY,mime TEXT NOT NULL,data BLOB NOT NULL,bytes INTEGER NOT NULL,created_at INTEGER NOT NULL,created_by TEXT NOT NULL);
CREATE TRIGGER royal_image_quota BEFORE INSERT ON product_images WHEN (SELECT COUNT(*) FROM product_images)>=100 BEGIN SELECT RAISE(ABORT,'image_quota'); END;
